# Dataframe com as f e fr como vetores
tab_frequencia <- data.frame(f = as.vector(f),
                             frp = as.vector(frp))

# Adicionar Frequência Absoluta Acumulada
tab_frequencia$F <- cumsum(tab_frequencia$f)

# Adicionar Frequência Relativa Acumulada (%)
